class Solution {
  public long maxScore(int[] points, int m) {
    long lo = 0, hi = 2_000_000_000_000_000L;
    while (lo < hi) {
      long mid = lo + (hi - lo + 1) / 2;
      if (feasible(points, m, mid)) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }

  private static boolean feasible(int[] points, long m, long x) {
    int n = points.length;
    long moves = 0, carry = 0;
    for (int i = 0; i < n; i++) {
      long need = (x + points[i] - 1) / points[i];
      if (i == n - 1 && carry >= need) break;
      moves++;
      long extra = Math.max(0, need - carry - 1);
      moves += 2 * extra;
      carry = extra;
      if (moves > m) return false;
    }
    return moves <= m;
  }
}
